export const Config = {
    tableRows: 50,
    modalRows: 10,
    currentPage: 1,
    offset: 0,
    isSuperUser: false,
    maxLimitPage: 10,
    colorPagination: "rgba(112, 111, 142, 0.16)",
    //mapIdGM: "c6d95126296646a5",
    timeReolad: 30000,
    timeOut: null,
    timeRoutineTopBar: null,
    currentUser: null,
    limitExport: 1000,
    timeOutExport: 200,
    isDepartmentEnabled: function(customerId) {
        if (!this.currentUser || !this.currentUser.business || !this.currentUser.business.urlUrb) {
            return false;
        }
        const allowedIds = this.currentUser.business.urlUrb.split(';');
        return allowedIds.includes(customerId);
    },
    currentScreen: null,
};
